   433→// ─── Location URL Conversion (formerly location.ts) ──────────────────────────
   434→
   435→function decodePathPart(value: string): string {
   436→  try { return decodeURIComponent(value); } catch { return value; }
   437→}
   438→
   439→function extractWorkspacePageSlug(path: string): string | null {
   440→  const pageMatch = path.match(/^\/workspace\/([^/]+)\/page\/(.+)$/);
   441→  if (!pageMatch) return null;
   442→  return pageMatch[2].split("/").map(decodePathPart).join("/");
   443→}
   444→
   445→function extractLegacyPageSlug(rawPagePath: string | null): string | null {
   446→  if (!rawPagePath) return null;
   447→  const pagePath = decodePathPart(rawPagePath);
   448→  const match = pagePath.match(/^pages\/(.+)\/SKILL\.md$/);
   449→  if (match) return match[1];
   450→  if (pagePath.startsWith("pages/")) {
   451→    return pagePath.slice("pages/".length).replace(/\/SKILL\.md$/, "");
   452→  }
   453→  return null;
   454→}
   455→
   456→function normalizeSearch(search?: string): string {
   457→  if (!search) return "";
   458→  return search.startsWith("?") ? search : `?${search}`;
   459→}
   460→
   461→function normalizeHash(hash?: string): string {
   462→  if (!hash) return "";
   463→  return hash.startsWith("#") ? hash : `#${hash}`;
   464→}
   465→
   466→function appendUrlSuffix(path: string, location: LocationUrlSuffix): string {
   467→  const search = normalizeSearch(location.search);
   468→  const hash = normalizeHash(location.hash);
   469→  if (!search) return `${path}${hash}`;
   470→  if (path.includes("?")) return `${path}&${search.slice(1)}${hash}`;
   471→  return `${path}${search}${hash}`;
   472→}
   473→
   474→function buildDetailQuery(
   475→  workspacePath: string | undefined,
   476→  extraParams?: Record<string, string | undefined>
   477→): string {
   478→  const params = new URLSearchParams();
